### Iteration 2: Shared Memory Optimization
Now let's optimize the kernel by using shared memory to reduce global memory accesses. We'll implement a tiled matrix multiplication approach where we load blocks of data into shared memory for faster access.

```python
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the optimized CUDA kernel using shared memory
matmul_optimized_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_SIZE 16

__global__ void matmul_kernel(const float* a, const float* b, float* c, int M, int N, int K) {
    // Shared memory for tiles of A and B
    __shared__ float A_tile[TILE_SIZE][TILE_SIZE];
    __shared__ float B_tile[TILE_SIZE][TILE_SIZE];

    int row = blockIdx.y * TILE_SIZE + threadIdx.y;
    int col = blockIdx.x * TILE_SIZE + threadIdx.x;

    float sum = 0.0f;

    // Loop over tiles
    for (int t = 0; t < (K + TILE_SIZE - 1) / TILE_SIZE; t++) {
        // Load tile of A into shared memory
        int a_col = t * TILE_SIZE + threadIdx.x;
        if (row < M && a_col < K) {
            A_tile[threadIdx.y][threadIdx.x] = a[row * K + a_col];
        } else {
            A_tile[threadIdx.y][threadIdx.x] = 0.0f;
        }

        // Load tile of B into shared memory
        int b_row = t * TILE_SIZE + threadIdx.y;
        if (b_row < K && col < N) {
            B_tile[threadIdx.y][threadIdx.x] = b[b_row * N + col];
        } else {
            B_tile[threadIdx.y][threadIdx.x] = 0.0f;
        }

        __syncthreads();  // Wait for all threads to load tiles

        // Compute partial dot product
        for (int k = 0; k < TILE_SIZE; k++) {
            sum += A_tile[threadIdx.y][k] * B_tile[k][threadIdx.x];
        }

        __syncthreads();  // Wait before loading next tiles
    }

    // Write result to output
    if (row < M && col < N) {
        c[row * N + col] = sum;
    }
}

torch::Tensor matmul_cuda(torch::Tensor a, torch::Tensor b) {
    // Input validation
    TORCH_CHECK(a.dim() == 2, "a must be 2D");
    TORCH_CHECK(b.dim() == 2, "b must be 2D");
    TORCH_CHECK(a.size(1) == b.size(0), "Inner dimensions must match");

    int M = a.size(0);
    int K = a.size(1);
    int N = b.size(1);

    auto c = torch::zeros({M, N}, a.options());

    // Set grid and block dimensions
    dim3 block(TILE_SIZE, TILE_SIZE);
    dim3 grid((N + TILE_SIZE - 1) / TILE_SIZE, (M + TILE_SIZE - 1) / TILE_SIZE);

    // Launch kernel
    matmul_kernel<<<grid, block>>>(a.data_ptr<float>(), b.data_ptr<float>(), c.data_ptr<float>(), M, N, K);

    // Check for kernel launch errors
    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        printf("Error in matmul_kernel: %s\\n", cudaGetErrorString(err));
    }
    return c;
}
"""

matmul_cpp_source = "torch::Tensor matmul_cuda(torch::Tensor a, torch::Tensor b);"

# Compile the inline CUDA code
matmul_module = load_inline(
    name='matmul_module',
    cpp_sources=matmul_cpp_source,
    cuda_sources=matmul_optimized_source,
    functions=['matmul_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self) -> None:
        super().__init__()

    def forward(self, x1, x2):
        return matmul_module.matmul_cuda(x1, x2)
