### Iteration 3: Larger Tile Size and Vectorized Loads
Let's further optimize by:
1. Increasing tile size to 32x32 for better data reuse
2. Using vectorized loads (float4) to reduce memory transactions
3. Padding shared memory to avoid bank conflicts

```python
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define optimized CUDA kernel with larger tile size and vectorized loads
matmul_optimized_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_SIZE 32
#define PAD 1  // Prevents bank conflicts

__global__ void matmul_kernel(const float* a, const float* b, float* c, int M, int N, int K) {
    // Shared memory for tiles with padding to avoid bank conflicts
    __shared__ float A_tile[TILE_SIZE][TILE_SIZE + PAD];
    __shared__ float B_tile[TILE_SIZE][TILE_SIZE + PAD];

    int row = blockIdx.y * TILE_SIZE + threadIdx.y;
    int col = blockIdx.x * TILE_SIZE + threadIdx.x;

    float sum = 0.0f;

    // Loop over tiles
    for (int t = 0; t < (K + TILE_SIZE - 1) / TILE_SIZE; t++) {
        // Vectorized load for A tile
        int a_col = t * TILE_SIZE + threadIdx.x;
        if (row < M && a_col < K) {
            // Load 4 elements at once using float4
            float4 val = *reinterpret_cast<const float4*>(&a[row * K + a_col]);
            A_tile[threadIdx.y][threadIdx.x] = val.x;
            if (threadIdx.x + 16 < TILE_SIZE) {
                A_tile[threadIdx.y][threadIdx.x + 16] = val.y;
            }
            if (threadIdx.x + 32 < TILE_SIZE) {
                A_tile[threadIdx.y][threadIdx.x + 32] = val.z;
            }
            if (threadIdx.x + 48 < TILE_SIZE) {
                A_tile[threadIdx.y][threadIdx.x + 48] = val.w;
            }
        } else {
            A_tile[threadIdx.y][threadIdx.x] = 0.0f;
        }

        // Vectorized load for B tile
        int b_row = t * TILE_SIZE + threadIdx.y;
        if (b_row < K && col < N) {
            // Load 4 elements at once using float4
            float4 val = *reinterpret_cast<const float4*>(&b[b_row * N + col]);
            B_tile[threadIdx.y][threadIdx.x] = val.x;
            if (threadIdx.x + 16 < TILE_SIZE) {
                B_tile[threadIdx.y][threadIdx.x + 16] = val.y;
            }
            if (threadIdx.x + 32 < TILE_SIZE) {
                B_tile[threadIdx.y][threadIdx.x + 32] = val.z;
            }
            if (threadIdx.x + 48 < TILE_SIZE) {
                B_tile[threadIdx.y][threadIdx.x + 48] = val.w;
            }
        } else {
            B_tile[threadIdx.y][threadIdx.x] = 0.0f;
        }

        __syncthreads();  // Wait for all threads to load tiles

        // Compute partial dot product with loop unrolling
        #pragma unroll
        for (int k = 0; k < TILE_SIZE; k++) {
            sum += A_tile[threadIdx.y][k] * B_tile[k][threadIdx.x];
        }

        __syncthreads();  // Wait before loading next tiles
    }

    // Write result to output
    if (row < M && col < N) {
        c[row * N + col] = sum;
    }
}

torch::Tensor matmul_cuda(torch::Tensor a, torch::Tensor b) {
    // Input validation
    TORCH_CHECK(a.dim() == 2, "a must be 2D");
    TORCH_CHECK(b.dim() == 2, "b must be 2D");
    TORCH_CHECK(a.size(1) == b.size(0), "Inner dimensions must match");

    int M = a.size(0);
    int K = a.size(1);
    int N = b.size(1);

    auto c = torch::zeros({M, N}, a.options());

    // Set grid and block dimensions
    dim3 block(TILE_SIZE, TILE_SIZE);
    dim3 grid((N + TILE_SIZE - 1) / TILE_SIZE, (M + TILE_SIZE - 1) / TILE_SIZE);

    // Launch kernel
    matmul_kernel<<<grid, block>>>(a.data_ptr<float>(), b.data_ptr<float>(), c.data_ptr<float>(), M, N, K);

    // Check for kernel launch errors
    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        printf("Error in matmul_kernel: %s\\n", cudaGetErrorString(err));
    }
    return c;
}
"""

